export const envelope = [11, 16, 27];

export default function build(api) {
  const [W, H, D] = api.size;

  // Theme palettes with safe fallbacks
  const wp = api.theme.wood?.planks || "minecraft:spruce_planks";
  const wl = api.theme.wood?.log || "minecraft:spruce_log";
  const ws = api.theme.wood?.stripped || "minecraft:stripped_spruce_log";
  const wst = api.theme.wood?.stairs || "minecraft:spruce_stairs";
  const wsl = api.theme.wood?.slab || "minecraft:spruce_slab";
  const wf = api.theme.wood?.fence || "minecraft:spruce_fence";
  const wt = api.theme.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const sp = api.theme.stone?.primary || "minecraft:stone";
  const sa = api.theme.stone?.accent || "minecraft:cobblestone";
  const sw = api.theme.stone?.wall || "minecraft:cobblestone_wall";
  const ssl = api.theme.stone?.slab || "minecraft:cobblestone_slab";

  const gp = api.theme.ground?.pavement || "minecraft:gravel";
  const gsc = api.theme.ground?.scree || "minecraft:coarse_dirt";
  const gpl = api.theme.ground?.plinth || "minecraft:andesite";

  function withState(blockStr, stateStr) {
    if (!blockStr) return "minecraft:spruce_log";
    if (blockStr.includes("[")) return blockStr;
    return `${blockStr}[${stateStr}]`;
  }

  const wlX = withState(wl, "axis=x");
  const wlY = withState(wl, "axis=y");
  const wlZ = withState(wl, "axis=z");
  const wsX = withState(ws, "axis=x");
  const wsY = withState(ws, "axis=y");
  const wsZ = withState(ws, "axis=z");

  // Local grid to construct ship before flushing
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      Array.from({ length: D }, () => null)
    )
  );

  function setB(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  // Hull profile curves
  function getKeelY(z) {
    if (z <= 1) return 6;
    if (z === 2) return 4;
    if (z === 3) return 3;
    if (z >= 25) return 6;
    if (z === 24) return 4;
    if (z === 23) return 3;
    return 2;
  }

  function getGunwaleY(z) {
    if (z <= 1) return 8;
    if (z === 2) return 7;
    if (z === 3) return 6;
    if (z >= 25) return 7;
    if (z === 24) return 6;
    return 5;
  }

  function getHalfWidth(z) {
    if (z <= 0 || z >= 26) return 0;
    if (z === 1 || z === 25) return 0.6;
    if (z === 2 || z === 24) return 1.3;
    if (z === 3 || z === 23) return 2.1;
    if (z === 4 || z === 22) return 2.8;
    if (z === 5 || z === 21) return 3.3;
    const t = (z - 5) / 16;
    return 3.5 + Math.sin(t * Math.PI) * 0.4;
  }

  // 1. Keel & Hull Shell
  for (let z = 1; z <= 25; z++) {
    const ky = getKeelY(z);
    const gy = getGunwaleY(z);
    const hw = getHalfWidth(z);

    // Keel spine
    setB(5, ky, z, wlZ);

    for (let y = ky; y <= gy; y++) {
      const nh = (y - ky) / Math.max(1, gy - ky);
      const rx = hw * Math.pow(nh, 0.45);
      const minX = Math.round(5 - rx);
      const maxX = Math.round(5 + rx);

      if (y === ky) {
        for (let x = minX; x <= maxX; x++) {
          setB(x, y, z, wp);
        }
      } else if (y === gy) {
        setB(minX, y, z, wsZ);
        setB(maxX, y, z, wsZ);
      } else {
        setB(minX, y, z, wp);
        setB(maxX, y, z, wp);
        if (y === ky + 1 && rx >= 1.8) {
          setB(minX + 1, y, z, wp);
          setB(maxX - 1, y, z, wp);
        }
      }
    }
  }

  // 2. Stem Post (Bow / North) & Stern Post (Aft / South)
  setB(5, 7, 0, wsZ);
  setB(5, 8, 0, withState(wt, "facing=north,half=bottom,open=false"));
  for (let y = 3; y <= 8; y++) setB(5, y, 1, wsY);
  for (let y = 2; y <= 5; y++) setB(5, y, 2, wlZ);

  for (let y = 3; y <= 7; y++) setB(5, y, 25, wsY);
  setB(5, 6, 26, wsZ);
  setB(5, 7, 26, withState(wt, "facing=south,half=bottom,open=false"));
  for (let y = 2; y <= 5; y++) setB(5, y, 24, wlZ);

  // 3. Internal Frames / Ribs & Keelson
  for (let z = 3; z <= 23; z++) {
    const ky = getKeelY(z);
    setB(5, ky + 1, z, wlZ);
  }

  const ribZ = [4, 7, 10, 13, 16, 19, 22];
  for (const rz of ribZ) {
    const ky = getKeelY(rz);
    const gy = getGunwaleY(rz);
    const hw = getHalfWidth(rz);
    const rx = Math.round(hw);

    setB(5 - rx + 1, ky + 1, rz, wsX);
    setB(5 + rx - 1, ky + 1, rz, wsX);

    // Thwart (cross beam)
    for (let x = 5 - rx + 1; x <= 5 + rx - 1; x++) {
      setB(x, gy - 1, rz, wsX);
    }
  }

  // 4. Decks
  // Foredeck (Z=3..6)
  for (let z = 3; z <= 6; z++) {
    const gy = getGunwaleY(z);
    const rx = Math.round(getHalfWidth(z));
    for (let x = 5 - rx + 1; x <= 5 + rx - 1; x++) {
      setB(x, gy - 1, z, wp);
    }
  }

  // Aftdeck (Z=20..23)
  for (let z = 20; z <= 23; z++) {
    const gy = getGunwaleY(z);
    const rx = Math.round(getHalfWidth(z));
    for (let x = 5 - rx + 1; x <= 5 + rx - 1; x++) {
      setB(x, gy - 1, z, wp);
    }
  }

  // Catwalk in open hold (Z=7..11, 17..19)
  for (let z = 7; z <= 11; z++) setB(5, 3, z, wp);
  for (let z = 17; z <= 19; z++) setB(5, 3, z, wp);

  // 5. Cargo & Ballast in Hold
  // Tin ore & raw smelt piles (Z=8..9)
  setB(4, 3, 8, "minecraft:raw_copper_block");
  setB(6, 3, 8, "minecraft:granite");
  setB(4, 3, 9, "minecraft:raw_iron_block");
  setB(6, 3, 9, "minecraft:dripstone_block");

  // Ballast stones in bilge (Z=10)
  setB(4, 3, 10, sa);
  setB(6, 3, 10, gpl);

  // Cargo trade bundles & casks (Z=17..18)
  setB(4, 3, 17, "minecraft:brown_wool");
  setB(6, 3, 17, "minecraft:white_wool");
  setB(4, 3, 18, sa);
  setB(6, 3, 18, ssl);

  // 6. Mast, Lowered Yardarm & Rigging
  for (let y = 3; y <= 13; y++) {
    setB(5, y, 11, wsY);
  }
  setB(5, 14, 11, withState(wt, "facing=north,half=bottom,open=false"));

  // Winter-beached lowered yardarm & furled sail (Y=8, Z=11)
  for (let x = 2; x <= 8; x++) {
    setB(x, 8, 11, wsX);
  }
  for (let x = 3; x <= 7; x++) {
    setB(x, 7, 11, "minecraft:light_gray_wool");
    setB(x, 6, 11, withState(wt, "facing=south,half=top,open=false"));
  }

  // Shrouds and Stays
  setB(5, 10, 10, wf);
  setB(5, 9, 9, wf);
  setB(5, 8, 7, wf);
  setB(5, 7, 5, wf);

  setB(5, 10, 12, wf);
  setB(5, 9, 14, wf);
  setB(5, 8, 17, wf);
  setB(5, 7, 19, wf);

  setB(4, 9, 11, wf);
  setB(3, 8, 11, wf);
  setB(2, 7, 11, wf);
  setB(2, 6, 11, wf);

  setB(6, 9, 11, wf);
  setB(7, 8, 11, wf);
  setB(8, 7, 11, wf);
  setB(8, 6, 11, wf);

  // 7. Steerboard (Starboard Quarter Rudder)
  setB(8, 5, 21, wf);
  setB(9, 5, 21, wsY);
  setB(9, 4, 22, wsY);
  setB(9, 3, 23, wsY);
  setB(9, 2, 23, wsY);
  setB(9, 1, 24, wsY);
  setB(9, 0, 24, wsY);

  // Tiller bar
  setB(8, 6, 21, wsX);
  setB(7, 6, 21, wsX);
  setB(6, 6, 21, wsX);

  // 8. Beaching Log Skids under Keel
  const skidZ = [5, 9, 13, 17, 21];
  for (const sz of skidZ) {
    for (let x = 3; x <= 7; x++) {
      setB(x, 1, sz, wlX);
    }
  }

  // 9. Hull Timber Props (Shores)
  // Starboard shores
  const sbShores = [8, 16];
  for (const pz of sbShores) {
    setB(8, 4, pz, wsY);
    setB(9, 3, pz, wsY);
    setB(9, 2, pz, wsY);
    setB(10, 1, pz, wsY);
  }

  // Port shores
  const ptShores = [8, 16];
  for (const pz of ptShores) {
    setB(2, 4, pz, wsY);
    setB(1, 3, pz, wsY);
    setB(1, 2, pz, wsY);
    setB(0, 1, pz, wsY);
  }

  // 10. Beach Unloading Station & Ballast Dumps
  // Port staging area (Z=12..14)
  setB(1, 1, 12, wp);
  setB(1, 1, 13, wp);
  setB(1, 1, 14, wp);
  setB(0, 1, 13, wlZ);
  setB(1, 2, 13, "minecraft:barrel[facing=up]");
  setB(1, 2, 12, wp);

  // Starboard ballast dump (Z=13..15)
  setB(9, 1, 13, sa);
  setB(9, 1, 14, gpl);
  setB(10, 1, 13, gp);
  setB(10, 1, 14, sa);
  setB(9, 2, 13, ssl);

  // 11. Ground Conformance: Project all supports & skids down to real terrain
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const h = Math.round(api.heightAt(x, z));

      // Find lowest placed voxel in this column
      let lowestY = -1;
      let lowestBlock = null;
      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null) {
          lowestY = y;
          lowestBlock = grid[x][y][z];
          break;
        }
      }

      if (lowestY !== -1) {
        // If column floats above terrain, extend continuous foundations down to h
        const targetMinY = Math.max(0, h);
        if (lowestY > targetMinY) {
          for (let y = lowestY - 1; y >= targetMinY; y--) {
            if (lowestBlock.includes("log") || lowestBlock.includes("stripped")) {
              grid[x][y][z] = y <= 0 ? sa : wlY;
            } else if (lowestBlock.includes("wool") || lowestBlock.includes("barrel")) {
              grid[x][y][z] = gp;
            } else {
              grid[x][y][z] = y <= 0 ? gsc : sa;
            }
          }
        }
      } else {
        // Build beach shingle collar around the grounded vessel
        const distToCenter = Math.abs(x - 5);
        if (distToCenter <= 4 && z >= 2 && z <= 24 && h >= 0 && h < 3) {
          const r = api.random();
          if (r < 0.4) {
            grid[x][h][z] = r < 0.2 ? gp : gsc;
          }
        }
      }
    }
  }

  // 12. Midwinter Frost & Snow Layers on Exposed Surfaces
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      for (let y = H - 2; y >= 0; y--) {
        const blk = grid[x][y][z];
        const above = grid[x][y + 1][z];
        if (blk !== null && above === null) {
          if (!blk.includes("fence") && !blk.includes("trapdoor") && !blk.includes("stairs")) {
            if (api.random() < 0.35) {
              grid[x][y + 1][z] = "minecraft:snow[layers=1]";
            }
          }
          break;
        }
      }
    }
  }

  // 13. Flush Grid to World
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] !== null) {
          api.set(x, y, z, grid[x][y][z]);
        }
      }
    }
  }

  return {
    name: "beached_trader",
    seatY: 0,
    anchors: {
      front: [5, 7, 0],
      gangway: [1, 2, 13]
    },
    interiors: [
      {
        min: [4, 3, 12],
        max: [6, 5, 16],
        kind: "hold"
      }
    ]
  };
}

