export const envelope = [22, 13, 22];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;

  // --- Theme Extraction & Safe Helpers ---
  const rawWoodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const rawWoodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const rawWoodStripped = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const rawWoodStairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const rawWoodSlab = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const rawWoodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const rawWoodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const rawStonePrimary = api.theme?.stone?.primary || "minecraft:cobblestone";
  const rawStoneAccent = api.theme?.stone?.accent || "minecraft:stone_bricks";
  const rawStoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const rawStoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const rawStoneWall = api.theme?.stone?.wall || "minecraft:cobblestone_wall";

  const rawGroundScree = api.theme?.ground?.scree || "minecraft:gravel";
  const rawGroundBank = api.theme?.ground?.bank || "minecraft:coarse_dirt";
  const rawGroundPlinth = api.theme?.ground?.plinth || "minecraft:stone";
  const rawGroundPavement = api.theme?.ground?.pavement || "minecraft:cobblestone";

  const rawRoofSolid = api.theme?.roof?.solid || rawWoodPlanks;
  const rawRoofSlab = api.theme?.roof?.slab || rawWoodSlab;
  const rawRoofStairs = api.theme?.roof?.stairs || rawWoodStairs;

  function cleanId(blockStr) {
    return blockStr.split("[")[0];
  }

  function logBlock(baseId, axis = "y") {
    return `${cleanId(baseId)}[axis=${axis}]`;
  }

  function stairsBlock(baseId, facing = "north", half = "bottom") {
    return `${cleanId(baseId)}[facing=${facing},half=${half}]`;
  }

  function slabBlock(baseId, type = "bottom") {
    return `${cleanId(baseId)}[type=${type}]`;
  }

  function trapdoorBlock(baseId, facing = "north", half = "bottom", open = false) {
    return `${cleanId(baseId)}[facing=${facing},half=${half},open=${open}]`;
  }

  // 3D Voxel Grid
  const grid = new Array(W);
  for (let x = 0; x < W; x++) {
    grid[x] = new Array(H);
    for (let y = 0; y < H; y++) {
      grid[x][y] = new Array(D).fill(null);
    }
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  // --- 1. Terrain Height Map & Conforming Bedrock Foundation ---
  const groundHeights = new Array(W);
  for (let x = 0; x < W; x++) {
    groundHeights[x] = new Array(D);
    for (let z = 0; z < D; z++) {
      const hLocal = api.heightAt(x, z);
      const gy = Math.max(1, Math.min(8, Math.round(seatY + hLocal)));
      groundHeights[x][z] = gy;

      // Fill base foundation below ground
      for (let y = 0; y <= gy; y++) {
        let b = rawGroundPlinth;
        const r = api.random();
        if (y === gy) {
          b = r < 0.45 ? rawGroundBank : (r < 0.8 ? "minecraft:coarse_dirt" : rawStonePrimary);
        } else if (y >= gy - 2) {
          b = r < 0.5 ? rawStonePrimary : (r < 0.8 ? "minecraft:granite" : rawGroundPlinth);
        } else {
          b = r < 0.4 ? rawGroundPlinth : (r < 0.7 ? "minecraft:tuff" : "minecraft:granite");
        }
        set(x, y, z, b);
      }
    }
  }

  // --- 2. Excavate the Open-Cast Tin Trench ---
  function getTrenchTargetHeight(x, z, gy) {
    const dx = (x - 12) / 6.2;
    const dz = (z - 12) / 6.2;
    const angle = Math.atan2(dz, dx);
    const wobble = 0.12 * Math.sin(angle * 3) + 0.08 * Math.cos(angle * 4);
    const r = Math.sqrt(dx * dx + dz * dz) + wobble;

    if (r > 1.05) {
      return gy; // Outside trench rim
    } else if (r > 0.72) {
      return Math.min(gy, 3); // Upper excavation terrace
    } else if (r > 0.42) {
      return Math.min(gy, 2); // Middle working bench
    } else {
      return 1; // Deep cassiterite ore sump
    }
  }

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const gy = groundHeights[x][z];
      const targetH = getTrenchTargetHeight(x, z, gy);

      if (targetH < gy) {
        // Hollow out air above trench floor
        for (let y = targetH + 1; y < H; y++) {
          set(x, y, z, "minecraft:air");
        }
        // Texture quarry floor and exposed ore
        for (let y = 0; y <= targetH; y++) {
          let b = rawGroundPlinth;
          const r = api.random();
          if (y === targetH) {
            if (r < 0.28) b = "minecraft:granite";
            else if (r < 0.50) b = rawStonePrimary;
            else if (r < 0.70) b = "minecraft:coarse_dirt";
            else if (r < 0.85) b = "minecraft:raw_copper_block"; // Cassiterite / tin ore
            else b = "minecraft:raw_iron_block";
          } else {
            b = r < 0.4 ? rawGroundPlinth : (r < 0.7 ? "minecraft:granite" : rawStonePrimary);
          }
          set(x, y, z, b);
        }
      }
    }
  }

  // --- 3. Timber Shoring & Wall Revetments ---
  const shoringPostPositions = [
    [7, 7], [10, 7], [13, 7], [16, 7],
    [7, 10], [7, 13], [7, 16],
    [10, 17], [13, 17], [16, 17],
    [17, 10], [17, 13], [17, 16]
  ];

  for (const [px, pz] of shoringPostPositions) {
    const gy = groundHeights[px][pz];
    const floorY = getTrenchTargetHeight(px, pz, gy);
    const postTop = Math.max(5, gy + 1);
    for (let y = Math.max(1, floorY); y <= postTop; y++) {
      set(px, y, pz, logBlock(rawWoodLog, "y"));
    }
  }

  // Horizontal waler beams bracing the shoring posts
  for (let x = 7; x <= 16; x++) {
    set(x, 3, 7, logBlock(rawWoodStripped, "x"));
    set(x, 4, 7, logBlock(rawWoodStripped, "x"));
    set(x, 3, 17, logBlock(rawWoodStripped, "x"));
    set(x, 4, 17, logBlock(rawWoodStripped, "x"));
  }
  for (let z = 7; z <= 17; z++) {
    set(7, 3, z, logBlock(rawWoodStripped, "z"));
    set(7, 4, z, logBlock(rawWoodStripped, "z"));
    set(17, 3, z, logBlock(rawWoodStripped, "z"));
    set(17, 4, z, logBlock(rawWoodStripped, "z"));
  }

  // Timber plank revetments behind the shoring posts
  for (let x = 8; x <= 15; x++) {
    for (let y = 2; y <= 4; y++) {
      if (get(x, y, 6) === "minecraft:air" || get(x, y, 6) === null) {
        set(x, y, 6, (x % 2 === 0) ? rawWoodPlanks : slabBlock(rawWoodSlab, "double"));
      }
      if (get(x, y, 18) === "minecraft:air" || get(x, y, 18) === null) {
        set(x, y, 18, (x % 2 === 0) ? rawWoodPlanks : rawStoneWall);
      }
    }
  }
  for (let z = 8; z <= 15; z++) {
    for (let y = 2; y <= 4; y++) {
      if (get(6, y, z) === "minecraft:air" || get(6, y, z) === null) {
        set(6, y, z, (z % 2 === 0) ? rawWoodPlanks : slabBlock(rawWoodSlab, "double"));
      }
      if (get(18, y, z) === "minecraft:air" || get(18, y, z) === null) {
        set(18, y, z, (z % 2 === 0) ? rawWoodPlanks : rawStoneWall);
      }
    }
  }

  // Diagonal raking props bracing the cut walls
  set(9, 2, 9, rawStonePrimary);
  set(8, 3, 8, rawWoodFence);
  set(15, 2, 9, rawStonePrimary);
  set(15, 3, 8, rawWoodFence);
  set(9, 2, 15, rawStonePrimary);
  set(8, 3, 16, rawWoodFence);
  set(15, 2, 15, rawStonePrimary);
  set(16, 3, 16, rawWoodFence);

  // --- 4. Gravel Spoil Mounds (Waste Tailings Heaps) ---
  // East Spoil Mound
  for (let x = 15; x <= 21; x++) {
    for (let z = 5; z <= 14; z++) {
      const dEast = Math.hypot((x - 19) / 3.8, (z - 9) / 4.2);
      if (dEast <= 1.0) {
        const moundH = Math.min(9, Math.round(9 - dEast * 5 + (api.random() * 0.6 - 0.3)));
        const gy = groundHeights[x][z];
        const startY = Math.max(1, Math.min(moundH, gy));
        for (let y = startY; y <= moundH; y++) {
          if (y < moundH - 1) {
            set(x, y, z, rawStonePrimary);
          } else if (y === moundH - 1) {
            const r = api.random();
            set(x, y, z, r < 0.5 ? rawStonePrimary : "minecraft:coarse_dirt");
          } else {
            const r = api.random();
            set(x, y, z, r < 0.5 ? rawGroundScree : (r < 0.8 ? "minecraft:coarse_dirt" : "minecraft:granite"));
          }
        }
      }
    }
  }

  // Northwest Spoil Mound
  for (let x = 1; x <= 6; x++) {
    for (let z = 1; z <= 5; z++) {
      const dNW = Math.hypot((x - 4) / 3.0, (z - 3) / 2.6);
      if (dNW <= 1.0) {
        const moundH = Math.min(7, Math.round(7 - dNW * 3.5 + (api.random() * 0.5 - 0.2)));
        const gy = groundHeights[x][z];
        const startY = Math.max(1, Math.min(moundH, gy));
        for (let y = startY; y <= moundH; y++) {
          if (y < moundH - 1) {
            set(x, y, z, rawStonePrimary);
          } else {
            const r = api.random();
            set(x, y, z, r < 0.55 ? rawGroundScree : "minecraft:coarse_dirt");
          }
        }
      }
    }
  }

  // --- 5. Ore Washing Sluice (Stream Tin Flume) ---
  const sluicePath = [
    { x: 4, z: 6, y: 5 }, { x: 4, z: 7, y: 5 }, { x: 4, z: 8, y: 5 },
    { x: 5, z: 9, y: 4 }, { x: 5, z: 10, y: 4 }, { x: 5, z: 11, y: 4 },
    { x: 6, z: 12, y: 3 }, { x: 6, z: 13, y: 3 }, { x: 6, z: 14, y: 3 }
  ];

  for (const seg of sluicePath) {
    // Trestle legs to ground
    const gy = groundHeights[seg.x][seg.z];
    const targetH = getTrenchTargetHeight(seg.x, seg.z, gy);
    for (let y = Math.max(1, targetH); y < seg.y; y++) {
      set(seg.x, y, seg.z, rawWoodFence);
    }

    // Flume bottom
    set(seg.x, seg.y, seg.z, rawWoodPlanks);

    // Channel wash contents (frozen stream ice, gravel & raw tin ore)
    const r = api.random();
    const washBlock = r < 0.4 ? "minecraft:packed_ice" : (r < 0.7 ? "minecraft:gravel" : "minecraft:raw_copper_block");
    set(seg.x, seg.y + 1, seg.z, washBlock);

    // Flume wooden sides
    set(seg.x - 1, seg.y + 1, seg.z, trapdoorBlock(rawWoodTrapdoor, "east", "bottom", true));
    set(seg.x + 1, seg.y + 1, seg.z, trapdoorBlock(rawWoodTrapdoor, "west", "bottom", true));
  }

  // Sluice settling vat / buddle basin at the flume discharge
  set(6, 1, 15, rawStonePrimary);
  set(6, 2, 15, "minecraft:cauldron");
  set(5, 2, 15, rawStoneWall);
  set(7, 2, 15, rawStoneWall);
  set(6, 2, 16, slabBlock(rawStoneSlab, "bottom"));

  // --- 6. Bronze Age Pithead Hoist / Tripod Derrick ---
  // Tripod Apex at (12, 10, 13)
  set(12, 10, 13, logBlock(rawWoodLog, "y"));

  // Leg 1 (North-West)
  const leg1Coords = [
    [10, 2, 11], [10, 3, 11], [11, 4, 12], [11, 5, 12],
    [11, 6, 12], [11, 7, 12], [12, 8, 13], [12, 9, 13]
  ];
  for (const [lx, ly, lz] of leg1Coords) {
    set(lx, ly, lz, rawWoodFence);
  }
  set(10, 1, 11, rawStonePrimary);

  // Leg 2 (North-East)
  const leg2Coords = [
    [14, 2, 11], [14, 3, 11], [13, 4, 12], [13, 5, 12],
    [13, 6, 12], [13, 7, 12], [12, 8, 13], [12, 9, 13]
  ];
  for (const [lx, ly, lz] of leg2Coords) {
    set(lx, ly, lz, rawWoodFence);
  }
  set(14, 1, 11, rawStonePrimary);

  // Leg 3 (South)
  const leg3Coords = [
    [12, 2, 16], [12, 3, 16], [12, 4, 15], [12, 5, 15],
    [12, 6, 14], [12, 7, 14], [12, 8, 13], [12, 9, 13]
  ];
  for (const [lx, ly, lz] of leg3Coords) {
    set(lx, ly, lz, rawWoodFence);
  }
  set(12, 1, 16, rawStonePrimary);

  // Cross lashings
  set(11, 5, 12, logBlock(rawWoodStripped, "x"));
  set(12, 5, 12, logBlock(rawWoodStripped, "x"));
  set(13, 5, 12, logBlock(rawWoodStripped, "x"));
  set(12, 5, 13, rawWoodFence);
  set(12, 5, 14, rawWoodFence);

  // Hanging chain & suspended ore basket
  for (let y = 5; y <= 9; y++) {
    set(12, y, 13, "minecraft:chain[axis=y]");
  }
  set(12, 4, 13, "minecraft:cauldron");

  // Winch windlass on the bench
  set(10, 3, 12, logBlock(rawWoodStripped, "z"));
  set(9, 3, 12, rawWoodFence);

  // --- 7. Miners' Lean-To Tool Shelter & Warming Hearth ---
  // Floor at y = 4 (for x in 8..14, z in 1..5)
  for (let x = 8; x <= 14; x++) {
    for (let z = 1; z <= 5; z++) {
      for (let y = 0; y <= 4; y++) {
        const r = api.random();
        set(x, y, z, r < 0.5 ? rawWoodPlanks : rawStonePrimary);
      }
      // Clear interior space
      for (let y = 5; y <= 7; y++) {
        set(x, y, z, "minecraft:air");
      }
    }
  }

  // Shelter upright posts
  for (let y = 4; y <= 8; y++) {
    set(8, y, 1, logBlock(rawWoodLog, "y"));
    set(14, y, 1, logBlock(rawWoodLog, "y"));
  }
  for (let y = 4; y <= 6; y++) {
    set(8, y, 5, logBlock(rawWoodLog, "y"));
    set(14, y, 5, logBlock(rawWoodLog, "y"));
  }

  // Shelter roof beams
  for (let x = 8; x <= 14; x++) {
    set(x, 8, 1, logBlock(rawWoodLog, "x"));
    set(x, 6, 5, logBlock(rawWoodLog, "x"));
  }
  for (let z = 1; z <= 5; z++) {
    const beamY = Math.round(8 - ((z - 1) / 4) * 2);
    set(8, beamY, z, rawWoodFence);
    set(14, beamY, z, rawWoodFence);
  }

  // Shed roof covering (sloping from y=8 down to y=6)
  for (let x = 7; x <= 15; x++) {
    set(x, 8, 0, slabBlock(rawRoofSlab, "top"));
    set(x, 8, 1, rawRoofSolid);
    set(x, 8, 2, stairsBlock(rawRoofStairs, "south", "bottom"));
    set(x, 7, 3, rawRoofSolid);
    set(x, 7, 4, stairsBlock(rawRoofStairs, "south", "bottom"));
    set(x, 6, 5, rawRoofSolid);
    set(x, 6, 6, slabBlock(rawRoofSlab, "bottom"));
  }

  // Back wall
  for (let x = 9; x <= 13; x++) {
    for (let y = 5; y <= 7; y++) {
      set(x, y, 1, rawWoodPlanks);
    }
  }

  // Warming Hearth for thawing frozen ground
  set(12, 4, 2, rawStonePrimary);
  set(12, 5, 2, "minecraft:campfire[lit=true]");
  set(11, 5, 2, rawStoneWall);
  set(13, 5, 2, rawStoneWall);
  set(12, 5, 1, rawStoneWall);

  // Miners' tool bench & ore storage bins
  set(9, 5, 2, rawStonePrimary);
  set(9, 6, 2, slabBlock(rawStoneSlab, "bottom"));
  set(10, 5, 2, "minecraft:raw_copper_block");
  set(10, 5, 3, "minecraft:raw_iron_block");
  set(9, 5, 4, rawWoodPlanks);

  // Hanging lantern under ridge beam
  set(11, 7, 3, "minecraft:lantern[hanging=true]");

  // --- 8. Ladders & Log Haulage Skid Ramp ---
  // Sump ladder (from y=2 to y=4 at shoring post 7, y, 10)
  for (let y = 2; y <= 4; y++) {
    set(7, y, 10, logBlock(rawWoodLog, "y"));
    set(8, y, 10, "minecraft:ladder[facing=east]");
  }

  // Terrace ladder (from y=3 to y=5 at shoring post 11, y, 17)
  for (let y = 3; y <= 5; y++) {
    set(11, y, 17, logBlock(rawWoodLog, "y"));
    set(11, y, 16, "minecraft:ladder[facing=north]");
  }

  // Timber haulage skid ramp along southeast slope
  set(14, 1, 15, rawStonePrimary);
  set(14, 2, 15, logBlock(rawWoodStripped, "x"));
  set(15, 2, 16, rawStonePrimary);
  set(15, 3, 16, logBlock(rawWoodStripped, "x"));
  set(16, 3, 17, rawStonePrimary);
  set(16, 4, 17, logBlock(rawWoodStripped, "x"));
  set(17, 4, 18, rawStonePrimary);
  set(17, 5, 18, logBlock(rawWoodStripped, "x"));

  // Skid guide fences
  set(13, 3, 15, rawWoodFence);
  set(14, 4, 16, rawWoodFence);
  set(15, 5, 17, rawWoodFence);

  // --- 9. Rich Tin Ore Lodes & Drainage Sump ---
  // Exposed cassiterite nuggets in pit floor
  set(12, 1, 12, "minecraft:raw_copper_block");
  set(13, 1, 12, "minecraft:raw_copper_block");
  set(13, 1, 13, "minecraft:raw_iron_block");
  set(14, 1, 14, "minecraft:granite");
  set(11, 1, 14, "minecraft:granite");

  // Frozen drainage water pool in lowest corner
  set(14, 1, 15, "minecraft:packed_ice");
  set(15, 1, 15, "minecraft:packed_ice");
  set(15, 1, 14, "minecraft:packed_ice");

  // --- 10. Midwinter Tundra Snow Layering Pass ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      // Find top solid block
      let topY = -1;
      for (let y = H - 1; y >= 0; y--) {
        const b = get(x, y, z);
        if (b !== null && b !== "minecraft:air") {
          topY = y;
          break;
        }
      }

      if (topY >= 1 && topY < H - 1) {
        const topBlock = get(x, topY, z);
        const isSheltered = (x >= 8 && x <= 14 && z >= 1 && z <= 5 && topY < 8);
        const isNearHearth = Math.hypot(x - 12, z - 2) <= 2.2;
        const isDeepPitFloor = (topY <= 2 && x >= 11 && x <= 15 && z >= 11 && z <= 15);

        // Place snow if top block is solid and exposed
        const isSolidBase = !topBlock.includes("fence") &&
                            !topBlock.includes("ladder") &&
                            !topBlock.includes("lantern") &&
                            !topBlock.includes("campfire") &&
                            !topBlock.includes("chain") &&
                            !topBlock.includes("cauldron");

        if (!isSheltered && !isNearHearth && !isDeepPitFloor && isSolidBase) {
          if (topY >= 7 && (x >= 16 || x <= 5)) {
            set(x, topY + 1, z, "minecraft:snow[layers=2]");
          } else {
            set(x, topY + 1, z, "minecraft:snow[layers=1]");
          }
        }
      }
    }
  }

  // --- 11. Physics Lint Pass (No Floating Gravity Blocks) ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      for (let y = 1; y < H; y++) {
        const b = get(x, y, z);
        if (b === rawGroundScree || b === "minecraft:gravel") {
          const below = get(x, y - 1, z);
          if (below === null || below === "minecraft:air") {
            set(x, y - 1, z, rawStonePrimary);
          }
        }
      }
    }
  }

  // --- 12. Deterministic Output Emission ---
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const b = grid[x][y][z];
        if (b !== null && b !== "minecraft:air") {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "tin_ore_pit",
    seatY: seatY,
    anchors: {
      front: [11, seatY, 0],
      door: [11, seatY, 0]
    },
    interiors: [
      {
        min: [9, 5, 2],
        max: [13, 7, 4],
        kind: "quarters"
      }
    ]
  };
}
